    /** The blocks the client tints by shade. */
    public static Block[] tinted() {
        return new Block[] {LAYTHE_SILT.get(), IKE_REGOLITH.get(), TUMOR.get()};
    }

    private static <T> java.util.List<T> reversed(T[] values) {
        java.util.List<T> list = new java.util.ArrayList<>(java.util.List.of(values));
        java.util.Collections.reverse(list);
        return list;
    }
